async page=>{const ctx=await page.context().browser().newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});const p=await ctx.newPage();const out=[];for(const width of [320,390,430,809]){await p.setViewportSize({width,height:844});for(const route of ['/','/case-studies/gaia','/index']){await p.goto('https://micahhoang.com'+route,{waitUntil:'domcontentloaded'});await p.addStyleTag({content:"@media (max-width: 809px) {\n    /* One existing page gutter across routes, including open-menu contents. */\n    nav[data-framer-name=\"Navigation\"] [data-framer-name=\"Mobile Navigation\"] :is(\n        [data-framer-name=\"Header\"], [data-framer-name=\"Routes\"], [data-framer-name=\"Social Links\"]\n    ),\n    body:has(.selected-work-grid) :is(\n        [data-framer-name=\"Section Hero\"], [data-framer-name=\"Header Bottom\"],\n        [data-framer-name=\"Section Selected Works\"], [data-framer-name=\"Section About\"]\n    ),\n    html body .idx-grid-preview-locked .idx-container,\n    html body [data-framer-name=\"Section CTA\"] > :is([data-framer-name=\"Tag Wrapper\"], [data-framer-name=\"Container\"]),\n    [data-framer-name=\"FooterBlackPhone\"], [data-framer-name=\"FooterWhitePhone\"] {\n        padding-inline: 20px !important;\n    }\n    /* The existing case-study footer scale, shared by every route and all four links.\n       Override older per-link patches before hydration, including the omitted GitHub row. */\n    html body [data-framer-name=\"Section CTA\"] [data-framer-name=\"CTA Row\"] {\n        align-items: flex-start !important;\n        flex-wrap: wrap !important;\n        gap: 10px !important;\n        height: auto !important;\n        min-height: 44px !important;\n        max-width: 100% !important;\n        padding: 0 !important;\n    }\n    html body [data-framer-name=\"Section CTA\"] [data-framer-name=\"CTA Row\"] > :first-child,\n    html body [data-framer-name=\"Section CTA\"] [data-framer-name=\"CTA Row\"] > :first-child * {\n        font-size: 32px !important;\n        line-height: 1em !important;\n        letter-spacing: -0.01em !important;\n        height: 32px !important;\n        min-height: 0 !important;\n        max-width: 100% !important;\n    }\n    html body [data-framer-name=\"Section CTA\"] [data-framer-name=\"CTA Row\"] > :not(:first-child) * {\n        font-size: 13px !important;\n        line-height: 1em !important;\n        letter-spacing: 0.01em !important;\n    }\n    html body .selected-work-tag,\n    html body .idx-grid-preview-locked .idx-grid-card-tag {\n        font-size: 13px !important;\n        line-height: 1.3 !important;\n    }\n}\n"});await p.waitForTimeout(800);out.push(await p.evaluate(()=>({w:innerWidth,path:location.pathname,overflow:document.documentElement.scrollWidth,header:[...document.querySelectorAll('[data-framer-name="Header"]')].filter(e=>e.getBoundingClientRect().width).map(e=>getComputedStyle(e).padding),cards:[...document.querySelectorAll('.selected-work-card,.idx-container')].slice(0,1).map(e=>({x:e.getBoundingClientRect().x,pad:getComputedStyle(e).padding})),cta:[...document.querySelectorAll('[data-framer-name="CTA Row"]')].filter(e=>e.getBoundingClientRect().width).map(e=>({text:e.textContent,w:e.getBoundingClientRect().width,h:e.getBoundingClientRect().height,x:e.getBoundingClientRect().x,font:getComputedStyle(e.querySelector('span')).fontSize,spacing:getComputedStyle(e.querySelector('span')).letterSpacing})),pills:[...document.querySelectorAll('.selected-work-tag,.idx-grid-card-tag')].slice(0,3).map(e=>({fs:getComputedStyle(e).fontSize,h:e.getBoundingClientRect().height,y:e.getBoundingClientRect().y}))})));} }await ctx.close();return out;}